INSERT INTO `dts_admin_announcements` (`id`, `title`, `message`, `target_type`, `target_value`, `is_active`, `starts_at`, `ends_at`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'Update on Incoming Documents', 'The Incoming Documents table has been updated to include the Regarding field. Users can now view the document’s subject and corresponding regarding details directly in the table, allowing for easier review and faster identification of document context without needing to open each record individually.', 'all', NULL, 1, '2026-07-09 07:00:00', '2026-07-09 18:00:00', 1, '2026-07-09 07:26:04', '2026-07-09 07:26:04'),
(2, 'Username Update Now Available', 'The Profile Settings page has been updated to allow users to change their username. Users may now update their account username directly from their profile. Once saved, the updated username will be used for the next login.', 'all', NULL, 1, '2026-07-13 08:00:00', '2026-07-16 18:00:00', 1, '2026-07-13 15:21:52', '2026-07-13 15:21:52'),
(3, 'DTS Update: Improved Document Search and Agency Display', 'For PMs users, the “TO” column has been replaced with “FROM”, and the agency abbreviation is now included in the display. The search function will return results based only on the information visible in the user’s table, such as the DTS No., Agency (From), Subject, Status, and Date Sent.\n\nOther user roles will continue to view and search documents based on the columns displayed in their respective tables.', 'all', NULL, 1, '2026-07-28 14:45:00', '2026-07-28 19:00:00', 1, '2026-07-28 14:49:35', '2026-07-28 14:49:35');
